import sys, json
from collections import deque

class Node:
    def __init__(self, val=0, left=None, right=None, next=None):
        self.val = val
        self.left = left
        self.right = right
        self.next = next

def build_tree(arr):
    if not arr: return None
    nodes = [Node(v) if v is not None else None for v in arr]
    it = iter(nodes)
    try:
        root = next(it)
    except StopIteration:
        return None
    queue = [root]
    for node in queue:
        if node:
            try:
                node.left = next(it)
                queue.append(node.left)
                node.right = next(it)
                queue.append(node.right)
            except StopIteration:
                break
    return root

def get_level_order_with_next(root):
    if not root: return []
    res = []
    curr = root
    while curr:
        temp = curr
        while temp:
            res.append(temp.val)
            temp = temp.next
        res.append(None)
        head = curr
        curr = None
        while head:
            if head.left:
                curr = head.left
                break
            if head.right:
                curr = head.right
                break
            head = head.next
    return res

def solve(root):
    if not root: return root
    queue = deque([root])
    while queue:
        n = len(queue)
        for i in range(n):
            node = queue.popleft()
            if i < n - 1:
                node.next = queue[0]
            if node.left: queue.append(node.left)
            if node.right: queue.append(node.right)
    return root

if __name__ == '__main__':
    line = sys.stdin.read().strip()
    if line:
        try:
            arr = json.loads(line)
            root = build_tree(arr)
            root = solve(root)
            print(json.dumps(get_level_order_with_next(root)).replace("None", "null"))
        except:
            print("[]")
    else:
        print("[]")

